// Parse and validate input
const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const CHUNK_THRESHOLD = 10000;

// Generate job_id if not provided
const jobIdProvided = !!body.job_id;
const jobId = body.job_id || 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
const projectId = headers['x-project-id'] || body.project_id || 'default';

// Determine pipeline type
let pipelineType = 'unknown';
let segments = [];
let needsChunking = false;
let totalSegments = 0;

if (body.segments && Array.isArray(body.segments) && body.segments.length > 0) {
  // Batch mode: multiple segments (commentaries)
  pipelineType = 'batch';
  segments = body.segments.map((s, idx) => ({
    index: idx,
    text: typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text),
    segment_id: s.segment_id || null,
    commentary_id: s.commentary_id || null,
    source_text: typeof s === 'string' ? s : null,
    // RFC bilingual-translations-en-pivot: EN pivot for quality
    reference_translation: s.reference_translation || null,
    char_count: (typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text || '')).length
  }));

  // Les segments trop longs ne sont plus rejetés : ils seront découpés puis
  // traduits morceau par morceau et RÉASSEMBLÉS (node « Pre-Translate Long »),
  // car le save est keyé par commentary_id (une ligne) — azy.daily#... (chunking batch).
  segments = segments.map(s => ({ ...s, needsChunk: s.char_count > CHUNK_THRESHOLD }));
  totalSegments = segments.length;

} else if (body.text) {
  // Single text mode
  const textLength = body.text.length;

  if (textLength > CHUNK_THRESHOLD) {
    pipelineType = 'chunk_then_translate';
    needsChunking = true;
    // Segments will be created by Chunk Worker
    segments = [{ index: 0, text: body.text, segment_id: body.segment_id || null, source_text: body.text, char_count: textLength }];
    totalSegments = 1; // Will be updated after chunking
  } else {
    pipelineType = 'translate_single';
    segments = [{
      index: 0,
      text: body.text,
      segment_id: body.segment_id || null,
      source_text: body.text,
      char_count: textLength
    }];
    totalSegments = 1;
  }
} else {
  return [{
    json: {
      valid: false,
      error: { code: 400, message: 'Either segments[] or text is required' }
    }
  }];
}

return [{
  json: {
    valid: true,
    useBatch: (Array.isArray(segments) && segments.length > 50),
    jobId: jobId,
    jobIdProvided: jobIdProvided,
    needsJobCreation: !jobIdProvided,
    projectId: projectId,
    jobType: body.job_type || 'translation',
    pipelineType: pipelineType,
    needsChunking: needsChunking,
    segments: segments,
    totalSegments: totalSegments,
    traite: body.traite,
    page: body.page,
    section: body.section,
    commentator: body.commentator,
    sourceLanguage: body.source_language || 'he',
    targetLanguage: body.target_language || 'fr',
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    context: body.context || {},
    metadata: body.metadata || {},
    requestId: body.request_id,
    model: body.model || 'claude-sonnet-4-6',
    provider: body.provider || 'anthropic',
    chunkThreshold: CHUNK_THRESHOLD
  }
}];

// Prepare segments for translation loop
const input = $('Parse Input').first().json;
const chunkResult = $input.first().json;

let segments = [];

// Check if chunking was done
if (chunkResult.segments && Array.isArray(chunkResult.segments)) {
  // Chunked segments from Chunk Worker
  segments = chunkResult.segments.map((s, idx) => ({
    index: idx,
    text: s.text,
    segment_id: input.segments[0]?.segment_id,
    source_text: input.segments[0]?.source_text,
    char_count: s.text?.length || 0,
    isChunk: true,
    totalChunks: chunkResult.segments.length
  }));
} else {
  // Use original segments (no chunking needed or chunking failed)
  segments = input.segments;
}

const items = segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: segments.length,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Use original segments directly (no chunking)
const input = $('Parse Input').first().json;

const items = input.segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: input.totalSegments,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Phase 2: Prepare save payload(s) - handle EN pivot generation
const loopItem = $('Loop Segments').first().json;
// Deux sources : Call Translate Worker (segment normal) OU le segment déjà réassemblé
// (long segment pré-traduit). On détecte via preTranslated.
const translateResult = loopItem.preTranslated
  ? { translation: loopItem.translation, success: true, method: loopItem.method || 'chunked_reassembled', generated_english: false }
  : $input.first().json;

// Base payload for target language translation
const targetPayload = {
  jobId: loopItem.jobId,
  segmentIndex: loopItem.index,
  totalSegments: loopItem.totalSegments,
  translation: translateResult.translation,
  segment_id: loopItem.segment_id,
  commentary_id: loopItem.commentary_id,
  source_text: loopItem.source_text,
  targetLanguage: loopItem.targetLanguage,
  model: loopItem.model,
  provider: loopItem.provider,
  metadata: loopItem.metadata,
  isChunk: loopItem.isChunk || false,
  pipelineType: loopItem.pipelineType,
  method: translateResult.method || 'unknown'
};

// Phase 2: If EN was generated, we need to save it first
const hasGeneratedEnglish = translateResult.generated_english === true && translateResult.english_pivot;

if (hasGeneratedEnglish) {
  // Return TWO items: first EN save, then target language save
  const englishPayload = {
    jobId: loopItem.jobId,
    segmentIndex: loopItem.index,
    totalSegments: loopItem.totalSegments,
    translation: translateResult.english_pivot,
    segment_id: loopItem.segment_id,
    commentary_id: loopItem.commentary_id,
    source_text: loopItem.source_text,
    targetLanguage: 'en',
    model: loopItem.model,
    provider: loopItem.provider,
    metadata: { ...loopItem.metadata, is_generated_pivot: true },
    isChunk: false,
    pipelineType: 'en_pivot_generation',
    method: 'structured_generation',
    isEnglishPivot: true
  };

  return [
    { json: englishPayload },
    { json: { ...targetPayload, hasEnglishPivotSaved: true } }
  ];
}

// No EN generation - just save target translation
return [{ json: targetPayload }];

// Update progress after each segment
const loopItem = $('Loop Segments').first().json;
const current = loopItem.index + 1;
const total = loopItem.totalSegments;
const percentage = Math.round((current / total) * 100);

return [{
  json: {
    jobId: loopItem.jobId,
    current: current,
    total: total,
    percentage: percentage,
    isLast: current >= total
  }
}];

// Pré-traduit les segments TROP LONGS (needsChunk) : découpe via le Chunk Worker,
// traduit chaque morceau via le Translate Worker, RÉASSEMBLE en UNE traduction.
// Indispensable car le save est keyé par commentary_id (une ligne) : sauver N morceaux
// sous le même id écraserait tout sauf le dernier. Les segments normaux passent inchangés.
const items = $input.all().map(i => i.json);
const nwh = $env.N8N_WEBHOOK_URL || 'http://localhost:5678';

const call = async (path, body) => this.helpers.httpRequest({
  method: 'POST', url: nwh + '/webhook/' + path, body, json: true, timeout: 300000,
});

const out = [];
for (const seg of items) {
  if (!seg.needsChunk) { out.push(seg); continue; }

  const ctx = { traite: seg.traite, page: seg.page, section: seg.section, commentator: seg.commentator };

  // 1. découper (Claude Smart Split — coupe sémantique)
  let chunkResp;
  try {
    chunkResp = await call('torah-chunk', {
      job_id: seg.jobId, text: seg.text, segment_id: seg.segment_id,
      threshold: seg.chunkThreshold, api_key: seg.apiKey, context: ctx,
    });
  } catch (e) { chunkResp = null; }

  if (!chunkResp || !chunkResp.success || !Array.isArray(chunkResp.segments) || !chunkResp.segments.length) {
    out.push({ ...seg, preTranslated: true, translation: null, longError: 'chunk_failed' });
    continue;
  }

  // 2. traduire chaque morceau DANS L'ORDRE
  const parts = [];
  let failed = null;
  for (const chunk of chunkResp.segments) {
    let tr;
    try {
      tr = await call('torah-translate', {
        job_id: seg.jobId, segment_id: seg.segment_id, text: chunk.text,
        reference_translation: null,
        source_language: seg.sourceLanguage, target_language: seg.targetLanguage,
        api_key: seg.apiKey, model: seg.model, context: ctx, metadata: seg.metadata,
      });
    } catch (e) { tr = null; }
    if (!tr || !tr.success || !tr.translation) { failed = 'chunk_translate_failed'; break; }
    parts.push(tr.translation);
  }

  // 3. réassembler
  out.push({
    ...seg, preTranslated: true,
    translation: failed ? null : parts.join('\n\n'),
    longError: failed,
    isChunk: false,
    chunksReassembled: chunkResp.segments.length,
    method: 'chunked_reassembled',
  });
}
return out.map(json => ({ json }));

